#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QUuid>
#include <iostream>
#include <cmath>
#include <stdexcept>
void check(bool ok,const QString& why){if(!ok)throw std::runtime_error(why.toStdString());}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument doc;auto source=SketchGeometry::addRectangle(SketchGeometry::newFeature(doc.authored()["documentId"].toString(),"XY"),{{"u1Mm",10},{"v1Mm",8},{"u2Mm",30},{"v2Mm",20}});QJsonArray ids;for(const auto& e:source["parameters"].toObject()["entities"].toArray())ids.append(e.toObject()["id"]);
 for(const auto& d:QJsonArray{QJsonObject{{"kind","horizontal"},{"entityId",ids[0]},{"valueMm",20}},QJsonObject{{"kind","vertical"},{"entityId",ids[1]},{"valueMm",12}}}){const auto s=SketchGeometry::addDimension(source,d.toObject());check(s.ok,s.error);source=s.feature;}
 const auto capture=SketchGeometry::copyProfileSelection(source,ids);check(capture.ok,capture.error);const auto clipboard=capture.diagnostics["clipboard"].toObject();const auto copyId=QUuid::createUuid().toString(QUuid::WithoutBraces);QJsonObject args{{"copyId",copyId},{"deltaUMm",35},{"deltaVMm",0}};
 const auto pasted=SketchGeometry::pasteProfile(source,clipboard,args);check(pasted.ok,pasted.error);auto copied=pasted.feature;const auto map=pasted.diagnostics["identityMap"].toObject();const auto newIds=pasted.diagnostics["copiedEntityIds"].toArray();check(newIds.size()==4 && SketchGeometry::evaluateFeature(copied).profiles.size()==2,"Two independent profiles");
 for(const auto& key:{"points","entities","constraints","dimensions"}){const auto before=source["parameters"].toObject()[key].toArray(),after=copied["parameters"].toObject()[key].toArray();check(after.size()==2*before.size(),"Clone every supported record");for(int n=0;n<before.size();++n){check(after[n]==before[n],"Source unchanged");check(before[n].toObject()["id"]!=after[n+before.size()].toObject()["id"],"Disjoint identities");}}
 for(const auto& row:source["parameters"].toObject()["points"].toArray()){const auto p=row.toObject();for(const auto& r:copied["parameters"].toObject()["points"].toArray()){const auto q=r.toObject();if(q["id"]==map[p["id"].toString()])check(std::abs(q["uMm"].toDouble()-p["uMm"].toDouble()-35)<1e-6 && q["vMm"]==p["vMm"],"Exact copied center coordinates");}}
 const auto again=SketchGeometry::pasteProfile(source,clipboard,args);check(again.ok && again.feature==copied,"Stable preview identities");
 for(double x:{0.,10.,20.}){auto bad=args;bad["deltaUMm"]=x;const auto rejected=SketchGeometry::pasteProfile(source,clipboard,bad);check(!rejected.ok && rejected.feature==source && rejected.error.contains("overlap"),"Overlap/edge contact refused atomically");}
 auto invalid=args;invalid["copyId"]="";check(!SketchGeometry::pasteProfile(source,clipboard,invalid).ok,"Missing copy token refused");
 const auto width=source["parameters"].toObject()["dimensions"].toArray().first().toObject().value("id");const auto sized=SketchGeometry::updateDimension(copied,{{"dimensionId",width},{"valueMm",24}});check(sized.ok,sized.error);for(const auto& key:{"points","entities","constraints","dimensions"}){const auto before=copied["parameters"].toObject()[key].toArray(),after=sized.feature["parameters"].toObject()[key].toArray();for(int n=before.size()/2;n<before.size();++n)check(before[n]==after[n],"Source size edit leaves copy independent");}
 const auto moved=SketchGeometry::translateProfile(sized.feature,{{"entityIds",newIds},{"deltaUMm",7},{"deltaVMm",-2}});check(moved.ok,moved.error);const auto profiles=SketchGeometry::evaluateFeature(sized.feature).profiles,afterMove=SketchGeometry::evaluateFeature(moved.feature).profiles;check(profiles.size()==2 && afterMove.size()==2,"Copied placement editable as ordinary geometry");
 auto twoLoops=SketchGeometry::addRectangle(source,{{"u1Mm",80},{"v1Mm",8},{"u2Mm",100},{"v2Mm",20}});const auto allEdges=twoLoops["parameters"].toObject()["entities"].toArray();const auto mixed=SketchGeometry::copyProfileSelection(twoLoops,QJsonArray{ids[0],ids[1],allEdges[4].toObject()["id"],allEdges[5].toObject()["id"]});check(!mixed.ok && mixed.feature==twoLoops,"Disconnected four-Line selection refused");
 const auto driven=SketchGeometry::addDimension(source,{{"kind","linear"},{"entityId",ids[2]},{"driving",false}});check(driven.ok,driven.error);const auto unsupported=SketchGeometry::copyProfileSelection(driven.feature,ids);check(!unsupported.ok && unsupported.feature==driven.feature,"Unsupported driven dimension refuses without silent loss");
 const auto disconnected=SketchGeometry::copyProfileSelection(source,QJsonArray{ids[0],ids[1],ids[2]});check(!disconnected.ok && disconnected.feature==source,"Incomplete selection refused");
 auto anchor=SketchGeometry::addStandalonePoint(source,{{"uMm",10},{"vMm",8}});check(anchor.ok,anchor.error);const auto anchorId=anchor.feature["parameters"].toObject()["entities"].toArray().last().toObject().value("pointId");const auto vertex=source["parameters"].toObject()["points"].toArray().first().toObject().value("id");auto linked=SketchGeometry::addConstraint(anchor.feature,{{"type","coincident"},{"pointIds",QJsonArray{vertex,anchorId}}});check(linked.ok,linked.error);check(!SketchGeometry::copyProfileSelection(linked.feature,ids).ok,"External relation is never silently dropped");
 check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),moved.feature),"Copy").isEmpty(),"Commit copied geometry");const auto authored=doc.authored();doc.history().undo();doc.history().redo();check(doc.authored()==authored,"Exact Undo/Redo");QTemporaryDir dir;check(doc.save(dir.filePath("copy.alloy")).isEmpty(),"Save");CadDocument reopened;check(reopened.open(dir.filePath("copy.alloy")).isEmpty() && reopened.authored()==authored,"Exact identity reopen");std::cout<<"SKETCH_COPY_CORE_OK\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
